CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,handle TEXT UNIQUE NOT NULL,pw TEXT NOT NULL,name TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',mode TEXT NOT NULL DEFAULT 'creator',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(th TEXT PRIMARY KEY,uid INTEGER NOT NULL,exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER NOT NULL,kind TEXT NOT NULL,body TEXT NOT NULL,link TEXT NOT NULL DEFAULT '',remix INTEGER,collab INTEGER,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS posts_uid ON posts(uid,id DESC);
CREATE TABLE IF NOT EXISTS tags(post INTEGER NOT NULL,uid INTEGER NOT NULL,PRIMARY KEY(post,uid));
CREATE TABLE IF NOT EXISTS likes(post INTEGER NOT NULL,uid INTEGER NOT NULL,PRIMARY KEY(post,uid));
CREATE TABLE IF NOT EXISTS follows(a INTEGER NOT NULL,b INTEGER NOT NULL,PRIMARY KEY(a,b));
CREATE TABLE IF NOT EXISTS msgs(id INTEGER PRIMARY KEY AUTOINCREMENT,a INTEGER NOT NULL,b INTEGER NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS msgs_ab ON msgs(a,b,id DESC);
CREATE INDEX IF NOT EXISTS msgs_ba ON msgs(b,a,id DESC);
CREATE TABLE IF NOT EXISTS ai_use(uid INTEGER NOT NULL,day TEXT NOT NULL,n INTEGER NOT NULL,PRIMARY KEY(uid,day));
CREATE TABLE IF NOT EXISTS saves(uid INTEGER PRIMARY KEY,data TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER NOT NULL,post INTEGER NOT NULL,target INTEGER NOT NULL,reason TEXT NOT NULL,created INTEGER NOT NULL,done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS blocks(a INTEGER NOT NULL,b INTEGER NOT NULL,PRIMARY KEY(a,b));
CREATE TABLE IF NOT EXISTS banned(uid INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS biz(uid INTEGER PRIMARY KEY,data TEXT NOT NULL,val INTEGER NOT NULL DEFAULT 0,ver INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY,v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stocks(sym TEXT PRIMARY KEY,name TEXT NOT NULL,owner INTEGER,price REAL NOT NULL,prev REAL NOT NULL,fair REAL NOT NULL,vol INTEGER NOT NULL DEFAULT 0,shares INTEGER NOT NULL,beta REAL NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS wallets(uid INTEGER PRIMARY KEY,cash REAL NOT NULL CHECK(cash>=0),realized REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS holds(uid INTEGER NOT NULL,sym TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>=0),avg REAL NOT NULL,PRIMARY KEY(uid,sym));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER NOT NULL,sym TEXT NOT NULL,side TEXT NOT NULL,qty INTEGER NOT NULL,limit_px REAL NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS orders_open ON orders(status,id);
CREATE TABLE IF NOT EXISTS trades(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER NOT NULL,sym TEXT NOT NULL,side TEXT NOT NULL,qty INTEGER NOT NULL,px REAL NOT NULL,fee REAL NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ticks(sym TEXT NOT NULL,t INTEGER NOT NULL,p REAL NOT NULL,PRIMARY KEY(sym,t));
